.motion-sample {
  --ml-accent: #c6f66b;
  --ml-ink: #13210d;
  box-sizing: border-box;
  position: relative;
  display: grid;
  place-items: center;
  width: 104px;
  height: 68px;
  border-radius: 10px;
  color: var(--ml-ink);
  background: var(--ml-accent);
  font: 700 20px/1 system-ui, sans-serif;
}

@keyframes ml-confirmation-halo {
  0%, 18% { transform: scale(.8); opacity: 0; }
  24% { opacity: .7; }
  70%, 100% { transform: scale(1.65); opacity: 0; }
}
.motion-sample { width: 52px; height: 52px; border-radius: 50%; font-size: 16px; }
.motion-sample::after { content: ""; position: absolute; inset: 0; border: 2px solid var(--ml-accent); border-radius: inherit; pointer-events: none; opacity: 0; animation: ml-confirmation-halo 3s ease-out infinite; }

@media (prefers-reduced-motion: reduce) {
  .motion-sample {
    animation: none !important;
    transition: none !important;
    transform: none !important;
    opacity: 1 !important;
    filter: none !important;
    clip-path: none !important;
    letter-spacing: normal !important;
  }
  .motion-sample::before,
  .motion-sample::after {
    animation: none !important;
    transition: none !important;
  }
}

// Author: Sergey Kosarevsky
// License: MIT
// Ported from https://gist.github.com/corporateshark/21d2fdd24c706952dc8c

uniform float pixelSize; // = 50.0

vec4 transition(vec2 uv) {
  float T = progress;
  float half_ = 0.5;
  float size = (T < half_) ? mix(1.0, pixelSize, T / half_) : mix(pixelSize, 1.0, (T - half_) / half_);
  float D = size * 0.005;
  // Remap UV to center the mosaic pattern
  vec2 UV = (uv - 0.5) / D;
  vec2 coord = clamp(D * (ceil(UV - 0.5)) + 0.5, 0.0, 1.0);
  vec4 C0 = getFromColor(coord);
  vec4 C1 = getToColor(coord);
  return mix(C0, C1, T);
}

// Author: Fernando Kuteken
// License: MIT

#define PI 3.141592653589

uniform float startingAngle; // = 90

vec4 transition (vec2 uv) {

  float offset = startingAngle * PI / 180.0;
  float angle = atan(uv.y - 0.5, uv.x - 0.5) + offset;
  float normalizedAngle = (angle + PI) / (2.0 * PI);

  normalizedAngle = normalizedAngle - floor(normalizedAngle);

  return mix(
    getFromColor(uv),
    getToColor(uv),
    step(normalizedAngle, progress)
    );
}

